// Property-based test patterns (fast-check + Vitest). Generated by `eos scaffold property-node`; yours to edit.
// Replace the toy functions with imports from your code. Good targets: parsers/serialisers (round trip),
// money maths (invariants), code with a simple reference implementation (oracle).
// Background: .eos/packs/ref/testing/property-fuzz.md   Dev dep: {{PM}} add -D fast-check
// A failure prints { seed, path }: pass them to fc.assert(..., { seed, path }) to replay it exactly.
import fc from "fast-check";
import { describe, expect, test } from "vitest";

// --- toy code under test (replace with imports) -------------------------------------------------------------
function splitAmount(totalCents: number, parts: number): number[] {
  const base = Math.floor(totalCents / parts);
  const rest = totalCents % parts;
  return Array.from({ length: parts }, (_, i) => base + (i < rest ? 1 : 0));
}
const encode = (data: unknown): string => JSON.stringify(data);
const decode = (text: string): unknown => JSON.parse(text);

const numRuns = process.env.CI ? 200 : 100; // fast-check's default is 100 runs per property

describe("properties", () => {
  // 1. invariants: hold for every valid input
  test("splitAmount keeps every cent", () => {
    fc.assert(
      fc.property(fc.integer({ min: 0, max: 1_000_000_000 }), fc.integer({ min: 1, max: 1000 }), (total, parts) => {
        const shares = splitAmount(total, parts);
        expect(shares.reduce((a, b) => a + b, 0)).toBe(total);
        expect(shares).toHaveLength(parts);
        expect(Math.max(...shares) - Math.min(...shares)).toBeLessThanOrEqual(1);
      }),
      { numRuns, examples: [[1, 3]] }, // pinned edge case, always tried first
    );
  });

  // 2. round trip: decode(encode(x)) equals x
  test("encode/decode round trip", () => {
    fc.assert(
      fc.property(fc.jsonValue(), (value) => {
        expect(decode(encode(value))).toEqual(value);
      }),
      { numRuns },
    );
  });

  // 3. oracle: compare with a slow, obviously correct reference
  test("sorting matches a reference", () => {
    fc.assert(
      fc.property(fc.array(fc.integer()), (xs) => {
        const reference = [...xs].sort((a, b) => a - b);
        expect(Int32Array.from(xs).sort()).toEqual(Int32Array.from(reference));
      }),
      { numRuns },
    );
  });
});
